import { mkdirSync, mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { ensureReplayArtifactsExcluded, extractExperimentId, extractExperimentUrl, resolveReplayArtifacts, writeExperimentPointer, writeRunMetadata, } from "./replayRunDir.js";
let dir;
beforeEach(() => {
    dir = mkdtempSync(join(tmpdir(), "replay-artifacts-"));
});
afterEach(() => {
    rmSync(dir, { recursive: true, force: true });
});
describe("resolveReplayArtifacts", () => {
    it("lays every artifact under the run directory by default", () => {
        const a = resolveReplayArtifacts({ runDir: join(dir, "run") });
        expect(a.runDir).toBe(resolve(dir, "run"));
        expect(a.logPath).toBe(resolve(dir, "run", "progress.log"));
        expect(a.eventsLogPath).toBe(resolve(dir, "run", "events.jsonl"));
        expect(a.itemsDir).toBe(resolve(dir, "run", "items"));
        expect(a.resultPath).toBe(resolve(dir, "run", "result.json"));
        expect(a.replaysRoot).toBe(resolve(dir));
        expect(a.runId).toMatch(/^\d{8}T.+-\d+-[0-9a-f]{8}$/);
    });
    it("mints a unique run dir under .bitfab/replays when none is given", () => {
        const a = resolveReplayArtifacts({});
        const b = resolveReplayArtifacts({});
        expect(a.runDir).toContain(join(".bitfab", "replays"));
        expect(a.runDir).not.toBe(b.runDir);
    });
    it("honors per-path overrides while defaulting the rest into the run dir", () => {
        const a = resolveReplayArtifacts({
            runDir: join(dir, "run"),
            out: join(dir, "custom-result.json"),
            logPath: join(dir, "custom.log"),
        });
        expect(a.resultPath).toBe(resolve(dir, "custom-result.json"));
        expect(a.logPath).toBe(resolve(dir, "custom.log"));
        expect(a.itemsDir).toBe(resolve(dir, "run", "items"));
    });
});
describe("extractExperimentId", () => {
    it("reads experimentId and experiment_id, or null", () => {
        expect(extractExperimentId({ experimentId: "a" })).toBe("a");
        expect(extractExperimentId({ experiment_id: "b" })).toBe("b");
        expect(extractExperimentId({})).toBeNull();
        expect(extractExperimentId(null)).toBeNull();
        expect(extractExperimentId("x")).toBeNull();
    });
    it("falls back to the older testRunId and test_run_id names", () => {
        expect(extractExperimentId({ testRunId: "a" })).toBe("a");
        expect(extractExperimentId({ test_run_id: "b" })).toBe("b");
    });
    it("prefers experimentId over the older name when both are present", () => {
        expect(extractExperimentId({ testRunId: "old", experimentId: "new" })).toBe("new");
    });
});
describe("extractExperimentUrl", () => {
    it("reads the new url names first, then the older ones", () => {
        expect(extractExperimentUrl({ experimentUrl: "a" })).toBe("a");
        expect(extractExperimentUrl({ experiment_url: "b" })).toBe("b");
        expect(extractExperimentUrl({ testRunUrl: "c" })).toBe("c");
        expect(extractExperimentUrl({ test_run_url: "d" })).toBe("d");
        expect(extractExperimentUrl({ testRunUrl: "old", experimentUrl: "new" })).toBe("new");
        expect(extractExperimentUrl({})).toBeNull();
    });
});
describe("ensureReplayArtifactsExcluded", () => {
    it("adds the runtime-artifact patterns to .git/info/exclude, once", () => {
        mkdirSync(join(dir, ".git"));
        const excludePath = join(dir, ".git", "info", "exclude");
        ensureReplayArtifactsExcluded(dir);
        const first = readFileSync(excludePath, "utf8");
        expect(first).toContain(".bitfab/replays/");
        expect(first).toContain("scripts/replay-result.json");
        // Idempotent: a second call must not duplicate the patterns.
        ensureReplayArtifactsExcluded(dir);
        const second = readFileSync(excludePath, "utf8");
        expect(second).toBe(first);
        expect(second.match(/\.bitfab\/replays\//g)).toHaveLength(1);
    });
    it("no-ops when there is no git dir above the start path", () => {
        expect(() => ensureReplayArtifactsExcluded(dir)).not.toThrow();
    });
});
describe("writeRunMetadata / writeExperimentPointer", () => {
    it("writes run.json with the run's identity and paths", () => {
        const artifacts = resolveReplayArtifacts({ runDir: join(dir, "run") });
        writeRunMetadata(artifacts, {
            label: "my-fn",
            startedAt: 1_700_000_000_000,
            status: "running",
            experimentId: "tr-1",
        });
        const run = JSON.parse(readFileSync(join(artifacts.runDir, "run.json"), "utf8"));
        expect(run).toMatchObject({
            runId: artifacts.runId,
            label: "my-fn",
            status: "running",
            experimentId: "tr-1",
            startedAt: new Date(1_700_000_000_000).toISOString(),
            finishedAt: null,
            resultPath: artifacts.resultPath,
        });
    });
    it("writes a by-experiment pointer back to the run directory", () => {
        const artifacts = resolveReplayArtifacts({ runDir: join(dir, "run") });
        writeExperimentPointer(artifacts, "tr-1");
        const pointer = JSON.parse(readFileSync(join(artifacts.replaysRoot, "by-experiment", "tr-1", "run.json"), "utf8"));
        expect(pointer).toMatchObject({
            experimentId: "tr-1",
            runId: artifacts.runId,
            runDir: artifacts.runDir,
            eventsLogPath: artifacts.eventsLogPath,
        });
    });
});
